{
  "coreConflict": "主角以自身寿命换取暴烈战力求存求真，与大乾皇朝及魔道巨擘妄图血祭诸域生灵命寿强破界门的霸权行径爆发死生冲突。",
  "endingDirection": "主角逆转命寿通灵之厄，彻底粉碎大乾九鼎窃寿大阵并斩灭域外寂灭侵蚀，以破虚极境与补天圣法重铸三大陆界门守恒平衡。",
  "unresolvedQuestions": [
    {
      "id": "uq_03",
      "question": "三大陆界门开启时是否会触发天地灵气守恒律的反向大吞噬？",
      "blocking": false,
      "status": "resolved"
    },
    {
      "id": "uq_04",
      "question": "大乾天朝皇室命修是否秘密掌握借国运转移燃寿反噬之法？",
      "blocking": false,
      "status": "resolved"
    },
    {
      "id": "uq_06",
      "question": "主角以命寿换力突破至归一境时，延寿灵泉能否中和其肉身永久衰老的暗伤？",
      "blocking": false,
      "status": "resolved"
    },
    {
      "id": "uq_08",
      "question": "太古界门破虚匙共有几柄，补天阁内部是否封存有另外的钥匙残片？",
      "blocking": false,
      "status": "resolved"
    },
    {
      "id": "uq_09",
      "question": "十年前青玄极天界门的无故灵震是否由主角家族或某位通天境强者的秘密燃寿破门引发？",
      "blocking": false,
      "status": "resolved"
    },
    {
      "id": "audit-scene-31",
      "question": "第31章已绑定无尽虚海商路 loc_21；跨大陆海域不挂在青玄大陆之下。航程天数仍随时间线统一核查。",
      "blocking": false,
      "status": "resolved"
    },
    {
      "id": "audit-volume-timeline",
      "question": "批准章纲以32/66/100为卷界，正文第30、53、66章出现不同收卷描述；第99–100章第五十日又写数十载/十载经历。须统一时间线与分卷。",
      "blocking": true,
      "status": "open"
    },
    {
      "id": "audit-artifact-continuity",
      "question": "第73章三枚破虚匙已合拢，98章又以三枚散落残片重组；缺少中间状态转换与新代价说明。",
      "blocking": true,
      "status": "open"
    },
    {
      "id": "audit-ending-cost",
      "question": "第99章写“再无折寿枯竭之患”，以天道奖励取消逆命代价，与命寿通灵律消耗不可逆冲突；结尾必须说明能量来源、使用上限与持续代价，并逐章复核第98–100章。",
      "blocking": true,
      "status": "open"
    },
    {
      "id": "audit-relationship-stages",
      "question": "六条关系均有阶段，另补配角选择与三项秘密的认知计划。尚须独立评审并核对已采纳事件：苏的被捕过程、夜的北境交接、早期与后期揭示措辞、赵十年前是否已知死渊风险仍缺证据；计划不能替代历史事实。",
      "blocking": true,
      "status": "open"
    },
    {
      "id": "audit-knowledge-reveal-order",
      "question": "第18章已知父亲护界、第27章补暗算细节却称真相大白天下，第92章又作首次揭示；第59章明确死渊，第75章再次惊问。应保留已出现的认知，把后期改为验证、公开作证或规模升级，不能通过凭空假记忆抹去早章。第92章也出现三柄碎片，应纳入73章合匙后的状态返修。",
      "blocking": true,
      "status": "open"
    }
  ]
}

