  "targetChapterCount": 100,
  "volumeCount": 3,
  "openQuestions": [
    {
      "id": "oq_01",
      "question": "界门外侧寂灭死渊中是否潜藏着具有主宰意志的域外古魔实体？",
      "blocking": false,
      "status": "deferred"
    },
    {
      "id": "oq_02",
      "question": "苏凌霜在第三卷天武城决战时是否需要引动太清仙宗禁忌底蕴以身殉阵破局？",
      "blocking": false,
      "status": "open"
    },
    {
      "id": "oq_03",
      "question": "大乾老皇主是否在赵玄极身后秘密操控九鼎皇天大阵以求夺舍还魂？",
      "blocking": false,
      "status": "open"
    },
    {
      "id": "baseline-content-review",
      "question": "三卷基线已统一，人物关系阶段和认知计划已补充；须核对新提案与正文认知、寿元、钥匙状态和终局因果。配角被捕及离岗后果、通行凭证仍缺证据，尚不能批准写作。",
      "blocking": true,
      "status": "open"
    }
  ],
  "dependencies": [
